-- LiveryLab Academy v50: lesson-specific reading material (no schema changes).
-- Keep exercise/task, quizzes, access plans, XP and user progress untouched.
-- The legacy sections remain stored for compatibility but the reader ignores their generic filler.
WITH cleaned AS (
  SELECT lesson_id, btrim(replace(replace(replace(replace(replace(payload->>'theory',' Im echten Softwareprojekt ist wichtiger als eine kurze Syntaxübung, wie du deinen Code in eine klare Funktion, wiederholbare Tests und eine saubere Benutzeroberfläche überführst. Überprüfe Datenformate, fehlende Werte und Fehlerzustände. Dokumentiere eine eigenständige Verbesserung.',''),' Dokumentiere jeweils die eigene Szene, den Ausgangszustand und deine Änderung. Im Handy-3D-Studio kannst du Grundformen und Transformationen üben, für die volle Anleitung ist Blender Desktop erforderlich.',''),' Dieses Thema hilft dir, das Verhalten deines Programms zu verstehen. Prüfe das Beispiel mit einer eigenen Variante, statt es nur zu kopieren.',''),' Lies den Beispielcode Zeile für Zeile. Überlege, welche Eingabe das Ergebnis verändert und welcher Fehler möglich ist.',''),' Baue die Funktion in kleinen Schritten, prüfe Sicherheitsgrenzen und dokumentiere den Fehlerfall.','')) AS theory
  FROM public.ll_lesson_content
)
UPDATE public.ll_lesson_content AS c
SET payload = jsonb_set(c.payload,'{theory}',to_jsonb(cleaned.theory),true)
FROM cleaned WHERE c.lesson_id=cleaned.lesson_id AND c.payload->>'theory'<>cleaned.theory;

