('html-08','["Ein Dashboard benötigt eine klare Überschriftenstruktur, Navigation, Hauptinhalt und verständliche Datenbereiche. HTML beschreibt die Bedeutung, CSS später die Darstellung."]'::jsonb,'["Kennzahlen lassen sich in sections gliedern und mit h2 beschriften, ohne alles als unstrukturierte div-Blöcke abzulegen."]'::jsonb),
('css-01','["CSS-Selektoren wählen HTML-Elemente aus. color verändert die Textfarbe, background-color den Hintergrund."]'::jsonb,'["h1 { color: blue; } färbt alle passenden Überschriften, während .titel gezielt Elemente mit dieser Klasse anspricht."]'::jsonb),
('css-02','["Das Box-Modell besteht aus Inhalt, padding, border und margin. box-sizing: border-box macht das Berechnen fester Breiten einfacher."]'::jsonb,'["Bei width: 200px und padding: 10px bleibt die Gesamtbreite mit border-box einschließlich Innenabstand bei 200px."]'::jsonb),
('css-03','["display:flex ordnet direkte Kindelemente auf einer Hauptachse an. justify-content wirkt entlang dieser Achse, align-items quer dazu."]'::jsonb,'["Bei flex-direction: row verteilt justify-content: space-between Elemente horizontal, während align-items: center sie vertikal ausrichtet."]'::jsonb),
('css-04','["CSS Grid arbeitet mit Zeilen und Spalten. grid-template-columns legt Spalten fest, gap die Zwischenräume."]'::jsonb,'["grid-template-columns: repeat(3, 1fr) erzeugt drei gleich breite Spalten innerhalb des Grids."]'::jsonb),
('css-05','["Media Queries ändern Styles abhängig von Eigenschaften des Anzeigegeräts. Mobile-first beginnt mit schmalen Ansichten und erweitert danach."]'::jsonb,'["Mit @media (min-width: 768px) kann ein einspaltiges Layout auf breiten Bildschirmen zwei Spalten erhalten."]'::jsonb),
('css-06','["Typografie wird mit font-size, line-height, font-weight und weiteren Eigenschaften gestaltet. Zeilenhöhe und Kontrast beeinflussen die Lesbarkeit."]'::jsonb,'["line-height: 1.5 gibt Textzeilen mehr Abstand, ohne die Buchstaben selbst zu vergrößern."]'::jsonb),
('css-07','["CSS-Transitions animieren den Wechsel zwischen Zuständen; @keyframes definiert eine selbstständige Animation über mehrere Zwischenstände."]'::jsonb,'["transition: transform .2s verändert die Bewegung beim Hover weich. prefers-reduced-motion sollte für weniger Animationen berücksichtigt werden."]'::jsonb),
('css-08','["Ein Designsystem verwendet wiederkehrende Farben, Abstände und Komponenten. CSS Custom Properties definieren Werte an einer gemeinsamen Stelle."]'::jsonb,'["Mit --accent: #805ad5 kannst du die Akzentfarbe in mehreren Regeln per var(--accent) wiederverwenden."]'::jsonb),
('sql-01','["Eine relationale Datenbank speichert Daten in Tabellen aus Zeilen und Spalten. Schlüssel identifizieren Einträge und verbinden Tabellen."]'::jsonb,'["Eine Tabelle spieler kann id und name enthalten. id bleibt eindeutig, auch wenn zwei Spieler denselben Namen haben."]'::jsonb),
('sql-02','["SELECT wählt Spalten, FROM nennt die Tabelle und WHERE filtert Datensätze anhand einer Bedingung."]'::jsonb,'["SELECT name FROM spieler WHERE level > 5 liefert nur Namen von Zeilen mit einem Level über fünf."]'::jsonb),
('sql-03','["INSERT legt neue Zeilen an; UPDATE ändert bestehende Zeilen. Ein WHERE bei UPDATE begrenzt, welche Datensätze geändert werden."]'::jsonb,'["UPDATE spieler SET level = 6 WHERE id = 2 betrifft gezielt einen Datensatz statt alle Spieler."]'::jsonb),
('sql-04','["ORDER BY sortiert Ergebnisse auf- oder absteigend. LIMIT beschränkt die Anzahl der ausgegebenen Zeilen."]'::jsonb,'["ORDER BY punkte DESC LIMIT 5 zeigt höchstens fünf Spieler, beginnend bei den höchsten Punkten."]'::jsonb),
('sql-05','["Ein JOIN verbindet Tabellen über passende Schlüssel. INNER JOIN liefert nur übereinstimmende Zeilen, LEFT JOIN behält alle linken Zeilen."]'::jsonb,'["spieler JOIN fahrzeuge ON fahrzeuge.owner_id = spieler.id verbindet ein Fahrzeug mit seinem Besitzer."]'::jsonb),
('sql-06','["SQL-Parameter übertragen Eingaben als Werte und nicht als Teil des SQL-Befehls. Das schützt vor SQL-Injection."]'::jsonb,'["WHERE name = ? erhält den Namen separat. Ein Anführungszeichen in der Eingabe verändert dann nicht die Abfragestruktur."]'::jsonb),
('sql-07','["BEGIN startet eine Transaktion; COMMIT bestätigt alle Änderungen, ROLLBACK verwirft sie. Das ist für zusammenhängende Schritte wichtig."]'::jsonb,'["Eine Überweisung sollte Abbuchung und Gutschrift gemeinsam abschließen, damit nicht nur einer der beiden Schritte gespeichert wird."]'::jsonb),
('sql-08','["Indizes beschleunigen passende Suchvorgänge, kosten aber Speicher und Schreibaufwand. EXPLAIN zeigt, wie die Datenbank eine Anfrage ausführt."]'::jsonb,'["Ein Index auf owner_id kann die Suche nach Fahrzeugen eines bestimmten Besitzers beschleunigen."]'::jsonb),
('sql-09','["Migrationen dokumentieren Schemaänderungen in nachvollziehbarer Reihenfolge. Jede Migration beschreibt, was an Tabellen oder Spalten geändert wird."]'::jsonb,'["Eine Migration fügt etwa eine Spalte hinzu. Weitere Umgebungen können denselben Änderungsschritt reproduzieren."]'::jsonb),
('sql-10','["oxmysql verbindet FiveM-Ressourcen mit einer SQL-Datenbank. Die Abfrage wird asynchron ausgeführt; Parameter und Ergebnisse gehören in den richtigen Ablauf."]'::jsonb,'["Eine serverseitige Abfrage kann den Kontostand laden. Der Client darf dabei keine ungeprüften SQL-Befehle vorgeben."]'::jsonb),
('fivem-01','["fxmanifest.lua beschreibt eine Resource: fx_version, game und die zu ladenden Dateien. Client- und Serverskripte laufen in verschiedenen Umgebungen."]'::jsonb,'["client_script ''client.lua'' wird auf dem Client geladen; server_script ''server.lua'' auf dem Server. Eine Datei gehört nur zur angegebenen Seite."]'::jsonb),
('fivem-02','["Eine Resource lässt sich über die Serverkonsole starten und stoppen. Änderungen an Skripten werden typischerweise erst nach einem Neustart der Resource wirksam."]'::jsonb,'["ensure ressourcenname sorgt dafür, dass die Resource gestartet ist. Stop und erneuter Start setzen ihren Laufzeitstatus zurück."]'::jsonb),
('fivem-03','["Client-Code ist für Darstellung und lokale Eingaben zuständig; Server-Code validiert und verändert vertrauenswürdige Spieldaten. Shared-Dateien sind beiden Seiten zugänglich."]'::jsonb,'["Ein Menü wird lokal angezeigt, aber Geld abbuchen oder Berechtigungen prüfen muss ein Serverhandler entscheiden."]'::jsonb),
('fivem-04','["RegisterCommand registriert einen Befehlsnamen samt Callback. Beim Auslösen erhält die Funktion unter anderem die ausführende source."]'::jsonb,'["Der Spieler tippt einen Befehl in die Konsole oder den Chat. FiveM ruft daraufhin die registrierte Funktion auf."]'::jsonb),
('fivem-05','["RegisterNetEvent registriert ein empfangbares Ereignis, AddEventHandler eine Reaktion darauf. Nicht jeder Event muss über das Netzwerk laufen."]'::jsonb,'["Ein internes Ereignis verbindet lokale Skriptteile; ein Netzwerkevent kann hingegen von einer anderen Laufzeitseite ausgelöst werden."]'::jsonb),
('fivem-06','["TriggerServerEvent sendet vom Client an den Server; TriggerClientEvent sendet vom Server an einen oder mehrere Clients."]'::jsonb,'["Eine Client-Schaltfläche kann eine Anfrage senden. Erst der Server prüft sie und sendet eine bestätigte Antwort zurück."]'::jsonb),
('fivem-07','["source bezeichnet bei Serverevents den auslösenden Spieler. Vor asynchronen Wartephasen sollte die ID lokal gesichert werden."]'::jsonb,'["In einem Eventhandler ist local src = source sicherer, wenn später ein Callback oder await-ähnlicher Ablauf auf die ID zugreift."]'::jsonb),
('fivem-08','["CreateThread startet nebenläufigen Lua-Code. Wait(ms) gibt der Laufzeit Zeit zurück, damit die Schleife andere Aufgaben nicht blockiert."]'::jsonb,'["Eine while-Schleife mit Wait(1000) prüft ungefähr einmal pro Sekunde; ohne Wait kann sie massiv Rechenzeit verbrauchen."]'::jsonb),
('fivem-09','["FiveM-Natives sind bereitgestellte Funktionen für Spielwelt und UI. Ihre Dokumentation zeigt Namen, Parameter, Rückgabe und die zulässige Skriptseite."]'::jsonb,'["Ein Native für Spielerposition benötigt die richtige Entity. Eine falsche Seite oder ungültige Entity liefert kein sinnvolles Ergebnis."]'::jsonb),
('fivem-10','["vector3 speichert drei Koordinaten. Die Entfernung zwischen Positionen ist wichtig für Näheprüfungen im Spiel."]'::jsonb,'["Ein Interaktionspunkt kann mit vector3(x,y,z) definiert werden; die Differenz zur Spielerposition ergibt eine Distanz."]'::jsonb),
('fivem-11','["Entities sind Spielobjekte wie Fahrzeuge und Pedestrians. Sie können erstellt, verändert und wieder gelöscht werden."]'::jsonb,'["Eine gespeicherte Entity-Referenz bleibt nicht automatisch für immer gültig. Vor einer Aktion sollte die Existenz geprüft werden."]'::jsonb),
('fivem-12','["Blips sind Kartensymbole; Position, Sprite und Farbe steuern ihre Darstellung. Sie sind visuelle Hinweise und keine serverseitigen Berechtigungen."]'::jsonb,'["Ein Blip kann einen Garagenstandort markieren, ohne automatisch eine Garage oder eine Interaktionszone zu erzeugen."]'::jsonb),
('fivem-13','["Eine nahe Position allein löst noch keine Aktion aus. Interaktion kombiniert Entfernung, Eingabe und gegebenenfalls einen sicheren Serveraufruf."]'::jsonb,'["Nur wenn der Spieler nah genug ist, wird eine Taste oder ein Hinweis angezeigt; die eigentliche Aktion kann auf dem Server geprüft werden."]'::jsonb),
('fivem-14','["Exports sind öffentlich angebotene Funktionen einer Resource für andere Resources. Sie vereinfachen das Teilen stabiler APIs."]'::jsonb,'["Eine Garage kann einen Export anbieten, den ein anderes Skript aufruft, ohne internen Code kopieren zu müssen."]'::jsonb),
('fivem-15','["Eine sichere FiveM-Aktion trennt Client-Anzeige von Serverentscheidung. Preis, Rechte und Ziel müssen serverseitig geprüft werden."]'::jsonb,'["Der Client sendet eine gewünschte Aktion; der Server ermittelt die echten Daten, prüft sie und meldet Erfolg oder Ablehnung zurück."]'::jsonb),
('blender-fundamentals-01','["Der 3D Viewport zeigt deine Szene, der Outliner listet Objekte und Properties enthalten deren Einstellungen. Jeder Editor hat einen anderen Zweck."]'::jsonb,'["Wenn du im Viewport einen Würfel auswählst, erscheint derselbe Eintrag im Outliner und seine Eigenschaften lassen sich rechts bearbeiten."]'::jsonb),
('blender-fundamentals-02','["Orbit dreht die Ansicht um einen Fokuspunkt, Pan verschiebt die Ansicht seitlich und Zoom verändert die Entfernung. Keine dieser Aktionen bewegt zwangsläufig das Objekt."]'::jsonb,'["Beim Orbit siehst du den Würfel von einer neuen Seite, obwohl seine Position in der Szene unverändert bleibt."]'::jsonb),
('blender-fundamentals-03','["Im Objektmodus bearbeitest du vollständige Objekte; im Edit Mode änderst du die Geometrie eines Meshes. Tab wechselt zwischen diesen Modi."]'::jsonb,'["G im Objektmodus verschiebt den ganzen Würfel; im Edit Mode können ausgewählte Eckpunkte einzeln verschoben werden."]'::jsonb),
('blender-fundamentals-04','["G bewegt, R dreht und S skaliert eine Auswahl. X, Y oder Z beschränken die Transformation auf eine Achse."]'::jsonb,'["Mit G, X und einem Zahlenwert bewegt sich ein Objekt gezielt auf der X-Achse statt frei im Raum."]'::jsonb),
('blender-fundamentals-05','["Der Outliner zeigt die Hierarchie der Szene. Collections bündeln zusammengehörige Objekte und können gemeinsam sichtbar oder unsichtbar sein."]'::jsonb,'["Eine Collection für Lichtquellen hält mehrere Lights organisiert, ohne sie zu einem einzigen Objekt zu verschmelzen."]'::jsonb),
('blender-fundamentals-06','["Ein erstes 3D-Projekt verbindet Modell, Material, Beleuchtung und Kamera. Exportformate transportieren je nach Format unterschiedliche Daten."]'::jsonb,'["Eine .blend-Datei enthält das bearbeitbare Projekt. Ein Export als glTF ist für den Austausch gedacht und speichert nicht alle Blender-Einstellungen."]'::jsonb),
('blender-fundamentals-21','["Vertices sind Eckpunkte, Edges verbinden zwei Punkte und Faces bilden Flächen. Aus diesen Teilen entsteht ein Mesh."]'::jsonb,'["Wenn du eine einzelne Ecke verschiebst, verändern die angrenzenden Kanten und Flächen ihre Form."]'::jsonb),
('blender-fundamentals-22','["Extrude erzeugt neue Geometrie aus ausgewählten Flächen oder Kanten. Inset bildet innerhalb einer Fläche einen neuen Rand."]'::jsonb,'["Mit Inset entsteht ein kleineres Rechteck innerhalb einer Fläche; Extrude kann daraus eine Vertiefung oder Erhöhung machen."]'::jsonb),
('blender-fundamentals-23','["Loop Cut fügt zusätzliche Kantenringe ein. Bevel rundet oder bricht scharfe Kanten durch zusätzliche Geometrie."]'::jsonb,'["Ein Würfel wirkt mit einem kleinen Bevel realistischer, weil seine Kanten Licht auf einer schmalen Fläche reflektieren."]'::jsonb),
('blender-fundamentals-24','["Snapping richtet Elemente an Punkten, Kanten oder Raster aus. Exakte Werte verhindern Lücken und ungewollte Überschneidungen."]'::jsonb,'["Zwei Wandmodule schließen sauber aneinander, wenn ihre Positionen am selben Raster ausgerichtet sind."]'::jsonb),
('blender-fundamentals-25','["Proportional Editing beeinflusst nicht nur ausgewählte Punkte, sondern auch nahe Geometrie mit abnehmender Stärke."]'::jsonb,'["Beim Anheben eines Vertex entsteht eine weiche Erhebung, wenn benachbarte Punkte mitbewegt werden."]'::jsonb),
('blender-fundamentals-41','["Materialfarben bestimmen die Grundfarbe, Roughness die Breite der Lichtreflexe und Metallic den metallischen Anteil einer Oberfläche."]'::jsonb,'["Niedrige Roughness erzeugt schärfere Spiegelungen, hohe Roughness verteilt das reflektierte Licht diffuser."]'::jsonb),
('blender-fundamentals-42','["Key Light ist die Hauptbeleuchtung, Fill Light hellt Schatten auf und Rim Light trennt Konturen vom Hintergrund."]'::jsonb,'["Ein Objekt wirkt räumlicher, wenn Hauptlicht, Aufhellung und Kantenlicht unterschiedliche Aufgaben übernehmen."]'::jsonb),
('blender-fundamentals-43','["Die Kamera bestimmt den sichtbaren Ausschnitt. Perspektive, Brennweite und Bildaufbau beeinflussen den Eindruck eines Modells."]'::jsonb,'["Eine tief platzierte Kamera lässt ein Fahrzeug oft mächtiger wirken als die gleiche Szene aus hoher Vogelperspektive."]'::jsonb),
('blender-fundamentals-44','["Eevee eignet sich für schnelle Echtzeitdarstellungen; Cycles simuliert Lichtwege aufwendiger. Beide Engines haben unterschiedliche Qualität- und Zeitkosten."]'::jsonb,'["Ein Wechsel der Render Engine kann Schatten, Reflexionen und Renderdauer deutlich verändern."]'::jsonb),
('blender-fundamentals-45','["Ein Portfolio-Render zeigt das fertige Modell mit gut gewählter Beleuchtung und Bildkomposition. Das eigentliche Mesh und der Render sind unterschiedliche Ergebnisse."]'::jsonb,'["Im finalen Bild wirkt dieselbe Geometrie durch Material, Kamera und Licht völlig anders als im grauen Viewport."]'::jsonb),
('qbcore-01','["QBCore bietet gemeinsame APIs und Spielerdaten für FiveM-Resources. Das Core Object ist der Einstiegspunkt für viele Framework-Funktionen."]'::jsonb,'["Ein Skript holt den Core-Zugriff und kann anschließend freigegebene Funktionen des Frameworks verwenden."]'::jsonb),
('qbcore-02','["PlayerData enthält aktuelle clientseitige Daten wie Job oder Status. Diese Kopie ist praktisch für die UI, aber keine Autoritätsquelle für Geldaktionen."]'::jsonb,'["Eine Anzeige kann PlayerData.job.name lesen; serverseitige Berechtigungen müssen trotzdem auf echten Serverdaten beruhen."]'::jsonb),
('qbcore-03','["Jobs enthalten Rollen wie police oder mechanic; Grades unterscheiden Stufen innerhalb eines Jobs. Beide Werte sind für Zugriffsentscheidungen relevant."]'::jsonb,'["Ein Menü kann nur für den passenden Job sichtbar sein; die serverseitige Aktion prüft Job und Grade erneut."]'::jsonb),
('qbcore-04','["Metadata speichert zusätzliche Spielerzustände. Je nach Frameworkversion können Werte fehlen und müssen defensiv gelesen werden."]'::jsonb,'["Ist ein Metadata-Feld nicht gesetzt, sollte ein geeigneter Standardwert statt eines ungeprüften nil-Zugriffs verwendet werden."]'::jsonb),
('qbcore-05','["QBCore.Functions.GetPlayer(source) holt serverseitig das Framework-Spielerobjekt. Es kann nil liefern, wenn der Spieler nicht mehr verbunden ist."]'::jsonb,'["Vor Player.Functions-Aufrufen muss geprüft werden, ob das Spielerobjekt existiert."]'::jsonb),
('qbcore-06','["Ein Spieler kann verschiedene Geldkonten besitzen. Kontostand und Kontotyp werden vom Server gelesen, nicht vom Browser oder Client vorgegeben."]'::jsonb,'["Beim Kauf darf das Skript das Konto bank nur aus serverseitigen Playerdaten auslesen."]'::jsonb),
('qbcore-07','["Eine Geldentfernung ist eine serverseitige Zustandsänderung. Betrag und Kontostand müssen vor dem Aufruf geprüft werden."]'::jsonb,'["Ist der Preis negativ oder das Guthaben zu klein, darf kein Geld entfernt und kein Artikel vergeben werden."]'::jsonb),
('qbcore-08','["Serverseitige Rechte sind entscheidend: Ein Client kann eigene UI-Zustände manipulieren. Rechte werden am Server aus verlässlichen Daten ermittelt."]'::jsonb,'["Ein Admin-Event prüft den auslösenden Spieler und seine erlaubte Rolle, bevor die Aktion ausgeführt wird."]'::jsonb),
('qbcore-09','["Shared Configs enthalten gemeinsame Einstellungen wie Preise oder Positionen. Geheime Schlüssel gehören nicht hinein, da sie auf Clients geladen werden können."]'::jsonb,'["Eine Config kann eine Garagenposition definieren; das Prüfen eines Kaufs bleibt trotzdem serverseitig."]'::jsonb),
('qbcore-10','["Server-Callbacks verbinden Anfrage und Antwort. Der Handler ermittelt Daten serverseitig und antwortet asynchron."]'::jsonb,'["Ein Client kann Fahrzeugdaten anfragen; der Server ruft den Callback erst nach seiner eigenen Prüfung mit den Ergebnissen auf."]'::jsonb),
('qbcore-11','["TriggerCallback startet auf Clientseite eine Callback-Anfrage. Das Ergebnis kommt später über eine Funktion zurück."]'::jsonb,'["Die UI wartet auf die Antwort und zeigt danach den erhaltenen Status statt einen sofort verfügbaren Rückgabewert zu erwarten."]'::jsonb),
('qbcore-12','["Useable Items verknüpfen ein Inventaritem mit einer Funktion. Die Aktion muss den verwendenden Spieler serverseitig identifizieren."]'::jsonb,'["Ein Reparaturkit kann eine Aktion auslösen; das Skript prüft Item und Spieler, bevor ein Effekt angewendet wird."]'::jsonb),
('qbcore-13','["Menüs sollten nur Aktionen darstellen und Eingaben sammeln; Logik für Kauf und Berechtigungen gehört in eine eigene Funktion."]'::jsonb,'["Die Menüoption ''Kaufen'' sendet eine Aktion, aber das Menü selbst setzt keinen Kontostand fest."]'::jsonb),
('qbcore-14','["Inventar-Integrationen brauchen eindeutige Itemnamen und klare Erfolg-/Fehlerbehandlung. APIs unterscheiden sich je nach Inventarsystem."]'::jsonb,'["Nach einem Kauf darf ein Item erst vergeben werden, wenn Geldaktion und Inventarprüfung erfolgreich waren."]'::jsonb),
('qbcore-15','["oxmysql führt parametrische SQL-Abfragen aus. Ergebnisse sind asynchron und müssen in der passenden Callback-Funktion verarbeitet werden."]'::jsonb,'["Ein SELECT kann gespeicherte Fahrzeuge laden; die Daten stehen erst nach Abschluss der Anfrage zur Verfügung."]'::jsonb),
('qbcore-16','["INSERT erstellt neue Zeilen und UPDATE ändert bestehende. Verwende Parameter für alle nutzerabhängigen Werte."]'::jsonb,'["Ein Kennzeichen wird als Abfrageparameter übergeben, statt es ungeprüft mit SQL-Text zu verketten."]'::jsonb),
('qbcore-17','["Eine Race Condition entsteht, wenn zwei gleichzeitige Aktionen denselben alten Zustand lesen. Transaktionen und geeignete Sperren sichern zusammengehörende Änderungen."]'::jsonb,'["Zwei gleichzeitige Käufe dürfen den Kontostand nicht beide auf Grundlage desselben alten Guthabens verringern."]'::jsonb),
('qbcore-18','["Fahrzeuge benötigen stabile Kennungen und eine Zuordnung zum Besitzer. Garagenlogik kombiniert Datenbankzustand mit dem tatsächlichen Fahrzeug in der Spielwelt."]'::jsonb,'["Ein Fahrzeugdatensatz beschreibt Besitz und Parkzustand, während die Entity eine konkrete Instanz im Spiel ist."]'::jsonb),
('qbcore-19','["Ein Resource-Restart beendet flüchtige Lua-Variablen. Dauerhafte Daten müssen in einer Datenbank gespeichert und wieder geladen werden."]'::jsonb,'["Ein vor dem Neustart gekauftes Fahrzeug darf nicht nur in einer lokalen Tabelle liegen, sonst verschwindet der Zustand."]'::jsonb),
('qbcore-20','["Eine Werkstatt-API bietet klar abgegrenzte Serveraktionen wie Auftrag starten und abschließen. Jede Aktion validiert Rollen und Eingaben."]'::jsonb,'["Ein Auftrag kann nur von einer autorisierten Werkstattrolle verändert werden; die UI zeigt lediglich den geprüften Status."]'::jsonb)
)
UPDATE public.ll_lesson_content AS c
SET payload=jsonb_set(jsonb_set(c.payload,'{explanation_steps}',reviewed.explanation_steps,true),'{example_notes}',reviewed.example_notes,true)
FROM reviewed WHERE c.lesson_id=reviewed.lesson_id;

UPDATE public.ll_lesson_index AS i
SET summary=left(split_part(c.payload->>'theory','.',1)||'.',350)
FROM public.ll_lesson_content AS c
WHERE c.lesson_id=i.id AND i.summary LIKE 'Du verstehst das Thema%' AND length(split_part(c.payload->>'theory','.',1))>=25;
